    } finally {
      stdout.forEach((bytes) => bytes.fill(0));
      stderr.forEach((bytes) => bytes.fill(0));
    }
  } finally {
    if (child) terminateOwnedChildTree(child);
    await finishLocalHub(run);
  }
}

